const test = require('node:test');
const assert = require('node:assert');
const { dedupe } = require('../src/dedupe');

test('the same object is not repeated', () => {
  const a = { id: 1, name: 'Ada' };
  assert.deepStrictEqual(dedupe([a, a]), [a]);
});

test('distinct contacts are all kept', () => {
  const list = [{ id: 1 }, { id: 2 }];
  assert.deepStrictEqual(dedupe(list), list);
});
