test('sorts by name and leaves the input alone', () => {
  const input = [{ name: 'Bo' }, { name: 'Al' }];
  assert.deepStrictEqual(byName(input).map((c) => c.name), ['Al', 'Bo']);
  assert.deepStrictEqual(input.map((c) => c.name), ['Bo', 'Al']);
